def fizzbuzz(n: int) -> str:
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "fizz"
    if n % 6 == 0:
        return "buzz"
    if n % 10 == 0:
        return "Buzz"
```


